        if !l.is_null() && f == l {
            return pyd_pickle_loads(args);
        }
    }
    pyd_call(f, pre, args, deep)
}

unsafe fn pyd_call(f: P, pre: &[V], args: &Args, deep: bool) -> R {
    let a = pyd_api();
    out_flush();
    let pa = pyd_args(pre, args)?;
    let r = (a.Call)(f, pa.t, pa.kw);
    if r.is_null() {
        return Err(pyd_err());
    }
    pyd_write_back(&pa)?;
    pyd_wrap(r, deep)
}

